"""Reviewer PoC (review-06): audit 'open' events carry no dir_fd, so the subject Closure hook resolves a dir_fd-relative name against the
process cwd. Shows (a) false admission: unpinned architecture file read through an fd on a non-governed parent with cwd '/', and
(b) false refusal: a non-governed target refused because the name is resolved under a governed cwd. Read-only; stdout only."""
import importlib.util, json, os, sys
from pathlib import Path
W = Path("/tmp/opensip-implementation/m1-report-projection-review-06/work")
ARCH = Path("/Users/sb/code/opensip-ai/opensip_arch")
s = importlib.util.spec_from_file_location("chk", W / "probe-copy/check.py"); chk = importlib.util.module_from_spec(s); s.loader.exec_module(chk)
closure = chk.Closure(ARCH, trace=False, out=W / "poc/fd-out.json")
closure.verify_pins(json.loads((W / "probe-copy/source-pins.json").read_bytes()))
sys.addaudithook(closure.hook)
chk.install_fresh_source_loader(closure)
res = {}
def attempt(name, fn):
    try:
        res[name] = {"outcome": "allowed", "value": fn()}
    except BaseException as exc:
        res[name] = {"outcome": "refused", "error": type(exc).__name__ + ": " + str(exc)[:160]}
readme = str(ARCH / "docs/implementation/README.md")
attempt("control-absolute-unpinned-read", lambda: len(open(readme, "rb").read()))
parent = os.open("/Users/sb/code/opensip-ai", os.O_RDONLY)
os.chdir("/")
def fd_read():
    fd = os.open("opensip_arch/docs/implementation/README.md", os.O_RDONLY, dir_fd=parent)
    try:
        return {"bytes": len(os.read(fd, 1 << 20)), "cwd": os.getcwd()}
    finally:
        os.close(fd)
attempt("a-dir_fd-relative-read-of-unpinned-arch-file-cwd-root", fd_read)
root_fd = os.open("/", os.O_RDONLY)
os.chdir(str(W / "poc"))
def fd_false_refusal():
    fd = os.open("etc", os.O_RDONLY, dir_fd=root_fd)
    os.close(fd)
    return "opened /etc via dir_fd"
attempt("b-dir_fd-relative-open-of-non-governed-/etc-with-governed-cwd", fd_false_refusal)
res["counts"] = closure.counts
sys.stdout.write(json.dumps(res, indent=1) + "\n")
